package export_wit_world

import (
	"fmt"

	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/executionruntime"
	pluginTypes "wit_component/ohrats_rc_plugin_types"
)

// Descriptor publishes the portable execution runtime over process policy, the
// RC Shell executor, and diagnostics reporting. It registers no CLI commands.
func Descriptor() pluginTypes.Descriptor {
	return pluginTypes.Descriptor{
		Id:      "ohrats:execution-runtime",
		Version: "0.1.1",
		Provides: []pluginTypes.Service{{
			Name:     "ohrats:rc-process/runtime",
			Version:  "0.3.0",
			Priority: 100,
			Keys:     []string{},
		}},
		Requires: []pluginTypes.Requirement{
			{
				Name:      "ohrats:rc-process/policy",
				Version:   "^0.3",
				Selection: pluginTypes.Selection_Single,
			},
			{
				Name:      "ohrats:rc-shell/executor",
				Version:   "^0.1",
				Selection: pluginTypes.Selection_Single,
			},
			{
				Name:      "ohrats:rc-diagnostics/reporting",
				Version:   "^0.1",
				Selection: pluginTypes.Selection_Single,
			},
		},
		Commands: []pluginTypes.Command{},
	}
}

// Activate reports the selected process and terminal backends.
func Activate() witTypes.Result[witTypes.Unit, string] {
	if err := executionruntime.Activate(); err != nil {
		return witTypes.Err[witTypes.Unit, string](err.Error())
	}
	return witTypes.Ok[witTypes.Unit, string](witTypes.Unit{})
}

// Deactivate has no component-local teardown; executions own their cleanup.
func Deactivate() {}

// Invoke rejects every command; the runtime exposes no CLI surface.
func Invoke(command string, _args []string) witTypes.Result[uint32, string] {
	return witTypes.Err[uint32, string](fmt.Sprintf("unsupported command %q", command))
}
